# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def format7(value: float) -> str:
    """Fixed 7 decimals, mapping -0.0000000 to 0.0000000 (as the Go edition does)."""
    text = "%.7f" % float(value)
    return "0.0000000" if text == "-0.0000000" else text


def cell_string(value) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "1" if value else "0"
    if isinstance(value, int):
        return str(value)
    return format7(value)


def xml_escape(text: str) -> str:
    out = []
    for ch in str(text):
        if ch == "&":
            out.append("&amp;")
        elif ch == "<":
            out.append("&lt;")
        elif ch == ">":
            out.append("&gt;")
        elif ch == '"':
            out.append("&quot;")
        elif ch == "'":
            out.append("&apos;")
        elif ch >= " " or ch in "\t\n\r":
            out.append(ch)
    return "".join(out)


def excel_col(index: int) -> str:
    name = ""
    while index > 0:
        index -= 1
        name = chr(ord("A") + index % 26) + name
        index //= 26
    return name


def human_size(size: int) -> str:
    if size < 1024:
        return "%d B" % size
    value = float(size)
    for unit in ("KB", "MB", "GB", "TB"):
        value /= 1024.0
        if value < 1024 or unit == "TB":
            return "%.2f %s" % (value, unit)
    return "%d B" % size


def format_count(value: int) -> str:
    return "{:,}".format(int(value))


def write_text_file(path: str, text: str) -> None:
    with open(path, "w", encoding="utf-8", newline="") as handle:
        handle.write(text)


# ---------------------------------------------------------------------------
# Loading and validating the embedded data
# ---------------------------------------------------------------------------

def _load_json(path: str):
    with open(path, "r", encoding="utf-8") as handle:
        return json.load(handle)


def treatment_display_name(code: str) -> str:
    names = PARAM_DB.get("treatments") or {}
    name = names.get(code)
    return name if name else code


def sorted_groups() -> list:
    groups = list(PARAM_DB.get("groups", {}).values())
    groups.sort(key=lambda g: (g.get("treatment", ""), g.get("L_mm", 0), g.get("D_mm", 0)))
    return groups


def sorted_curve_groups(db: dict | None = None) -> list:
    db = db if db is not None else CURVE_DB
    groups = list(db.get("groups", {}).values())
    groups.sort(key=lambda g: (
        TREATMENT_RANK.get(g.get("treatment"), 3),
        g.get("L_mm", 0),
        g.get("D_mm", 0),
        g.get("group", ""),
    ))
    return groups


def curve_group_row_count(group: dict) -> int:
    if not group.get("data_available"):
        return 0
    total = sum(len(spec.get("x_norm") or []) for spec in group.get("specimens") or [])
    if group.get("model1"):
        total += len(group["model1"].get("x_norm") or [])
    if group.get("model2"):
        total += len(group["model2"].get("x_norm") or [])
    return total


def curve_row_total(db: dict | None = None) -> int:
    db = db if db is not None else CURVE_DB
    return sum(curve_group_row_count(g) for g in db.get("groups", {}).values())


def treatment_curve_row_count(treatment: str, db: dict | None = None) -> int:
    db = db if db is not None else CURVE_DB
    return sum(curve_group_row_count(g) for g in db.get("groups", {}).values()
               if g.get("treatment") == treatment)


def missing_curve_groups(db: dict | None = None) -> list:
    db = db if db is not None else CURVE_DB
    return [g["group"] for g in sorted_curve_groups(db) if not g.get("data_available")]


def validate_parameter_database(param: dict) -> None:
    groups = param.get("groups") or {}
    if len(groups) != 27:
        raise ValueError("27 cases are required, but %d were found" % len(groups))
    for key, group in groups.items():
        if key != group.get("group"):
            raise ValueError("case key and identifier differ: %s" % key)
        if group.get("tau_u_MPa", 0) <= 0 or group.get("s_u_mm", 0) <= 0:
            raise ValueError("invalid calibrated parameters: %s" % key)
        if not 0 < group.get("b", 0) < 1:
            raise ValueError("invalid calibrated parameters: %s" % key)
        if group.get("L_mm", 0) <= 0 or group.get("D_mm", 0) <= 0:
            raise ValueError("invalid geometry parameters: %s" % key)


def validate_curve_database(db: dict) -> None:
    if db.get("schema_version") != "2.0":
        raise ValueError("Origin curve database version must be 2.0, got %r" % db.get("schema_version"))
    groups = db.get("groups") or {}
    if len(groups) != 27:
        raise ValueError("Origin curve database must hold 27 cases, got %d" % len(groups))
    available = 0
    for key, group in groups.items():
        if key != group.get("group"):
            raise ValueError("Origin curve case key and identifier differ: %s" % key)
        if group.get("treatment") not in TREATMENTS:
            raise ValueError("invalid Origin curve surface treatment: %s=%s" % (key, group.get("treatment")))
        if group.get("L_mm", 0) <= 0 or group.get("D_mm", 0) <= 0:
            raise ValueError("invalid Origin curve geometry parameters: %s" % key)
        if not group.get("data_available"):
            if group.get("specimens") or group.get("model1") or group.get("model2"):
                raise ValueError("%s is marked as missing data but still carries curves" % key)
            continue
        available += 1
        specimens = group.get("specimens") or []
        if len(specimens) != 3:
            raise ValueError("%s must have 3 specimen curves, got %d" % (key, len(specimens)))
        if len(group.get("su_repeats_mm") or []) != 3 or len(group.get("tau_repeats_MPa") or []) != 3:
            raise ValueError("%s must have 3 repeated su/tau values" % key)
        for index, series in enumerate(specimens):
            _validate_series(series, "%s specimen %d" % (key, index + 1))
        if not group.get("model1") or not group.get("model2"):
            raise ValueError("%s is missing its Model 1/Model 2 curves" % key)
        _validate_series(group["model1"], key + " Model 1")
        _validate_series(group["model2"], key + " Model 2")
    if available != 27:
        raise ValueError("Origin curve database must have 27 available cases, got %d" % available)
    if db.get("available_group_count") != available:
        raise ValueError("Origin curve database available_group_count=%s does not match the actual %d"
                         % (db.get("available_group_count"), available))
    if db.get("unavailable_groups"):
        raise ValueError("Origin curve database should have no missing cases, got %r"
                         % (db.get("unavailable_groups"),))


def _validate_series(series: dict, label: str) -> None:
    xs = series.get("x_norm") or []
    ys = series.get("y_norm") or []
    if series.get("n", 0) <= 0:
        raise ValueError("%s has no curve points" % label)
    if len(xs) != series["n"] or len(ys) != series["n"]:
        raise ValueError("%s: independent X/Y lengths disagree with n: n=%d, len(x)=%d, len(y)=%d"
                         % (label, series["n"], len(xs), len(ys)))


def _read_bytes(path: str) -> bytes:
    with open(path, "rb") as handle:
        return handle.read()


def _unpack(blob: str) -> bytes:
    """Decode one embedded resource: base64 text of zlib-compressed bytes."""
    return zlib.decompress(base64.b64decode(blob))


def load_databases() -> None:
    """Decode the embedded databases and web files, validate them, build /api/data."""
    global PARAM_DB, CURVE_DB, API_BYTES, STATIC_FILES

    param_text = _unpack(_PARAM_B64).decode("utf-8")
    param = json.loads(param_text)
    validate_parameter_database(param)
    param_text = json.dumps(param, ensure_ascii=False, separators=(",", ":"))

    curve_bytes = _unpack(_CURVE_B64).strip()
    curve = json.loads(curve_bytes.decode("utf-8"))
    validate_curve_database(curve)

    PARAM_DB = param
    CURVE_DB = curve

    # The API payload is the parameter database with the raw Origin curves appended, so
    # the 25 MB of curve points are never re-serialised.
    if not param_text.endswith("}"):
        raise ValueError("unexpected parameter database JSON shape")
    API_BYTES = param_text[:-1].encode("utf-8") + b',"origin_curves":' + curve_bytes + b"}"

    STATIC_FILES = {
        "index.html": _unpack(_INDEX_B64),
        "app.css": _unpack(_CSS_B64),
        "app.js": _unpack(_JS_B64),
    }


# ---------------------------------------------------------------------------
# CSV export (12 columns)
# ---------------------------------------------------------------------------

def export_series(group: dict) -> list:
    series = []
    for index, specimen in enumerate(group.get("specimens") or []):
        # Paper specimen label: case ID -1/2/3 (matching the Origin column C label).
        series.append({
            "name": "%s-%d" % (group["group"], index + 1),
            "kind": KIND_SPECIMEN,
            "source": SOURCE_SPECIMEN,
            "curve": specimen,
            "su": group["su_repeats_mm"][index],
            "tau": group["tau_repeats_MPa"][index],
        })
    for name, key in (("Model 1", "model1"), ("Model 2", "model2")):
        curve = group.get(key)
        if not curve:
            continue
        series.append({
            "name": name,
            "kind": KIND_MODEL,
            "source": SOURCE_MODEL,
            "curve": curve,
            "su": group["su_mm"],
            "tau": group["tau_u_MPa"],
        })
    return series


def export_row(group: dict, series: dict, point_index: int, x_norm: float, y_norm: float) -> list:
    return [
        group["group"],
        treatment_display_name(group.get("treatment", "")),
        group["L_mm"],
        group["D_mm"],
        series["name"],
        series["kind"],
        point_index,
        x_norm,
        y_norm,
        x_norm * series["su"],
        y_norm * series["tau"],
        series["source"],
    ]


def emit_curve_group_rows(group: dict, emit) -> None:
    for series in export_series(group):
        curve = series["curve"]
        xs = curve.get("x_norm") or []
        ys = curve.get("y_norm") or []
        for index in range(len(xs)):
            emit(export_row(group, series, index + 1, xs[index], ys[index]))


def treatment_curve_rows(treatment: str, emit) -> None:
    emit(CURVE_HEADERS)
    for group in sorted_curve_groups():
        if not group.get("data_available") or group.get("treatment") != treatment:
            continue
        emit_curve_group_rows(group, emit)


def missing_marker_row(group: dict) -> list:
    return [
        group["group"],
        group["treatment"],
        str(group["L_mm"]),
        str(group["D_mm"]),
        "Data missing",
        "Data missing",
        "0",
        "",
        "",
        "",
        "",
        "Origin worksheet is empty (0 rows); no simulated data was substituted",
    ]


def write_curve_csv(handle, db: dict | None = None) -> None:
    """Stream the 27 cases x 5 curves CSV (UTF-8 BOM + 1 header row)."""
    db = db if db is not None else CURVE_DB
    text = io.TextIOWrapper(handle, encoding="utf-8", newline="", write_through=True)
    try:
        text.write("\ufeff")
        writer = csv.writer(text, lineterminator="\n")
        writer.writerow(CURVE_HEADERS)
        for group in sorted_curve_groups(db):
            if not group.get("data_available"):
                continue
            emit_curve_group_rows(group, lambda values: writer.writerow([cell_string(v) for v in values]))
        for group in sorted_curve_groups(db):
            if group.get("data_available"):
                continue
            writer.writerow(missing_marker_row(group))
        text.flush()
    finally:
        text.detach()


# ---------------------------------------------------------------------------
# XLSX export (5 worksheets, standard library only)
# ---------------------------------------------------------------------------

def collect_export_stats(db: dict | None = None):
    db = db if db is not None else CURVE_DB
    specimen_rows = 0
    model_rows = 0
    groups_by_treatment = {t: 0 for t in TREATMENTS}
    rows_by_treatment = {t: 0 for t in TREATMENTS}
    for group in db.get("groups", {}).values():
        if not group.get("data_available"):
            continue
        treatment = group.get("treatment")
        groups_by_treatment[treatment] = groups_by_treatment.get(treatment, 0) + 1
        rows = 0
        for specimen in group.get("specimens") or []:
            count = len(specimen.get("x_norm") or [])
            specimen_rows += count
            rows += count
        for key in ("model1", "model2"):
            curve = group.get(key)
            if curve:
                count = len(curve.get("x_norm") or [])
                model_rows += count
                rows += count
        rows_by_treatment[treatment] = rows_by_treatment.get(treatment, 0) + rows
    return specimen_rows, model_rows, groups_by_treatment, rows_by_treatment


def summary_rows(db: dict, emit) -> None:
    emit(SUMMARY_HEADERS)
    for index, group in enumerate(sorted_curve_groups(db)):
        counts = [0, 0, 0]
        model1_n = model2_n = 0
        if group.get("data_available"):
            for i, specimen in enumerate(group.get("specimens") or []):
                if i < 3:
                    counts[i] = len(specimen.get("x_norm") or [])
            if group.get("model1"):
                model1_n = len(group["model1"].get("x_norm") or [])
            if group.get("model2"):
                model2_n = len(group["model2"].get("x_norm") or [])
        available = "No"
        status = "Data missing (Origin worksheet empty; no curve points generated)"
        if group.get("data_available"):
            available = "Yes"
            status = "Complete (Origin five curves: 3 specimens + 2 models)"
        emit([
            index + 1, group["group"], treatment_display_name(group.get("treatment", "")),
            group["L_mm"], group["D_mm"], group["su_mm"], group["tau_u_MPa"],
            counts[0], counts[1], counts[2], model1_n, model2_n,
            curve_group_row_count(group), available, status,
        ])


def docs_rows(db: dict | None = None) -> list:
    db = db if db is not None else CURVE_DB
    specimen_rows, model_rows, _, _ = collect_export_stats(db)
    total_rows = specimen_rows + model_rows
    missing = len(missing_curve_groups(db))
    available = db.get("available_group_count", 0)
    return [
        ["Item", "Description"],
        ["Data source",
         "data/origin_curve_database.json (schema 2.0), exported point by point from the Origin 9.8 "
         "project \"Normalized fitting curves - 1216 adjustment.opju\"; all 27 cases are available. "
         "The original UN-L50-D16 worksheet was empty and was recovered from the Origin figure embedded "
         "in the final paper DOCX (Figure 11(a)); the X/Y values stored in that figure were read out, "
         "not digitised from a screenshot."],
        ["Curve composition",
         "Five curves per case: specimens 1/2/3 (columns A/B, C/D, E/F) + Model 1 (G/H) + Model 2 (I/J); "
         "%d cases x 5 = %d curves, each with its own independent X/Y array." % (available, available * 5)],
        ["Normalisation convention",
         "x_norm = S/Su, y_norm = tau/tau_u; Origin already normalised them. This export uses "
         "x_norm/y_norm directly and never divides by su or tau_u again."],
        ["Rebuilding the original units",
         "s_mm = x_norm x su; tau_MPa = y_norm x tau_u. Specimens use their own su_repeats_mm / "
         "tau_repeats_MPa; Models 1/2 use the group means su_mm / tau_u_MPa. The rebuilt columns are "
         "for auditing only and do not feed the plots."],
        ["Curve point statistics",
         "Specimen curves %s rows + model curves %s rows = %s curve data rows; the CSV adds 1 header row "
         "+ %s missing-case marker rows, i.e. %s data rows in total."
         % (format_count(specimen_rows), format_count(model_rows), format_count(total_rows),
            format_count(missing), format_count(total_rows + missing))],
        ["Worksheet row counts",
         "%s: %d rows (with header); UN_curves: %d rows; PE_curves: %d rows; EM_curves: %d rows; "
         "%s: this sheet."
         % (SUMMARY_SHEET, 1 + len(db.get("groups", {})),
            1 + treatment_curve_row_count("UN", db), 1 + treatment_curve_row_count("PE", db),
            1 + treatment_curve_row_count("EM", db), DOCS_SHEET)],
        ["Missing cases",
         "None. All 27 cases are complete. The original UN-L50-D16 OPJU worksheet and Graph2 were empty; "
         "its three specimens and two models come from the Origin figure embedded in the final paper DOCX "
         "(Figure 11(a)), with provenance recorded in the JSON data_provenance and in extraction_report.json. "
         "If a case ever goes missing again, the summary sheet marks Data available = No and the CSV "
         "appends one \"Data missing\" marker row."],
        ["Model curve convention",
         "Origin's Model 1 / Model 2 point arrays are authoritative; this export neither re-fits nor "
         "substitutes formula values. Equations (3) and (4) of the paper are recorded here only as "
         "reference formulas for the GUI's custom parameters."],
        ["Paper Eq. (3), piecewise",
         "x<=1: y = a*x + (3-2a)x^2 + (a-2)x^3; x>1: y = 1/[b*(alpha*x + x^(-alpha))], alpha = (1-b)/b."],
        ["Paper Eq. (4), rational",
         "y = [Fm*x + (Gm-1)x^2] / [1 + (Fm-2)x + Gm*x^2]."],
        ["Data column description",
         "Case ID, Surface treatment, L_mm, D_mm, Curve name (specimens use the case ID -1/2/3, e.g. "
         "UN-L50-D8-1; models use Model 1/Model 2), Curve type, Point, Normalized slip S/Su, Normalized "
         "bond stress tau/tauu, Rebuilt slip_mm, Rebuilt bond stress_MPa, Data source."],
        ["Numeric format",
         "Every numeric column keeps 7 decimals; -0.0000000 is normalised to 0.0000000; negative values "
         "are not clipped (Origin Model 2 may show negative stress at large slip)."],
        ["Units",
         "Slip: mm; bond stress: MPa; L and D: mm; su_mm and tau_u_MPa are the group-mean peak parameters."],
        ["How it was generated",
         "app.py (Python edition) batch export: the GUI batch-export ZIP, or the command line "
         "--export <dir> for CSV/XLSX/README."],
    ]


def workbook_sheets(db: dict | None = None) -> list:
    db = db if db is not None else CURVE_DB
    specs = [{
        "name": SUMMARY_SHEET,
        "columns": len(SUMMARY_HEADERS),
        "row_count": 1 + len(db.get("groups", {})),
        "rows": lambda emit, d=db: summary_rows(d, emit),
    }]
    for treatment in TREATMENTS:
        specs.append({
            "name": treatment + "_curves",
            "columns": len(CURVE_HEADERS),
            "row_count": 1 + treatment_curve_row_count(treatment, db),
            "rows": lambda emit, t=treatment: treatment_curve_rows(t, emit),
        })
    docs = docs_rows(db)
    columns = max(2, max(len(row) for row in docs)) if docs else 2
    specs.append({
        "name": DOCS_SHEET,
        "columns": columns,
        "row_count": len(docs),
        "rows": lambda emit, rows=docs: [emit(row) for row in rows],
    })
    return specs


def rich_text(text: str) -> str:
    """Header cell: one bold white Times New Roman run."""
    return ('<r><rPr><b/><rFont val="Times New Roman"/><color rgb="FFFFFFFF"/></rPr>'
            '<t xml:space="preserve">%s</t></r>' % xml_escape(text))


def write_row_xml(out, row_index: int, values: list) -> None:
    header = row_index == 1
    style = ' s="1"' if header else ""
    parts = ['<row r="%d">' % row_index]
    for column, value in enumerate(values, 1):
        ref = excel_col(column) + str(row_index)
        if isinstance(value, str):
            if header:
                parts.append('<c r="%s"%s t="inlineStr"><is>%s</is></c>' % (ref, style, rich_text(value)))
            else:
                parts.append('<c r="%s" t="inlineStr"><is><t xml:space="preserve">%s</t></is></c>'
                             % (ref, xml_escape(value)))
        elif isinstance(value, bool):
            parts.append('<c r="%s"%s><v>%d</v></c>' % (ref, style, 1 if value else 0))
        elif isinstance(value, int):
            parts.append('<c r="%s"%s><v>%d</v></c>' % (ref, style, value))
        elif isinstance(value, float):
            parts.append('<c r="%s"%s><v>%s</v></c>' % (ref, style, format7(value)))
        else:
            raise TypeError("unsupported cell type %r at row %d column %d"
                            % (type(value).__name__, row_index, column))
    parts.append("</row>")
    out.write("".join(parts))


def write_sheet(spec: dict, handle) -> None:
    out = io.TextIOWrapper(handle, encoding="utf-8", newline="", write_through=True)
    try:
        dimension = "A1:%s%d" % (excel_col(spec["columns"]), spec["row_count"])
        out.write(XML_DECL + '<worksheet %s><dimension ref="%s"/>' % (MAIN_NS, dimension) +
                  '<sheetViews><sheetView workbookViewId="0">'
                  '<pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/>'
                  '</sheetView></sheetViews><sheetFormatPr defaultRowHeight="16"/><sheetData>')
        counter = {"rows": 0}

        def emit(values):
            counter["rows"] += 1
            write_row_xml(out, counter["rows"], values)

        spec["rows"](emit)
        if counter["rows"] != spec["row_count"]:
            raise RuntimeError("worksheet %s: expected %d rows, wrote %d"
                               % (spec["name"], spec["row_count"], counter["rows"]))
        out.write("</sheetData></worksheet>")
        out.flush()
    finally:
        out.detach()


def content_types_xml(specs: list) -> str:
    parts = [XML_DECL,
             '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">',
             '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
             '<Default Extension="xml" ContentType="application/xml"/>',
             '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',
             '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>']
    for index in range(len(specs)):
        parts.append('<Override PartName="/xl/worksheets/sheet%d.xml" '
                     'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                     % (index + 1))
    parts.append("</Types>")
    return "".join(parts)


def workbook_xml(specs: list) -> str:
    parts = [XML_DECL,
             '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
             'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>']
    for index, spec in enumerate(specs, 1):
        parts.append('<sheet name="%s" sheetId="%d" r:id="rId%d"/>'
                     % (xml_escape(spec["name"]), index, index))
    parts.append("</sheets></workbook>")
    return "".join(parts)


def workbook_rels_xml(specs: list) -> str:
    parts = [XML_DECL, '<Relationships %s>' % REL_NS]
    for index in range(len(specs)):
        parts.append('<Relationship Id="rId%d" Type="%s/worksheet" Target="worksheets/sheet%d.xml"/>'
                     % (index + 1, REL_TYPE, index + 1))
    parts.append('<Relationship Id="rId%d" Type="%s/styles" Target="styles.xml"/>'
                 % (len(specs) + 1, REL_TYPE))
    parts.append("</Relationships>")
    return "".join(parts)


def write_workbook(handle, db: dict | None = None) -> None:
    """Stream a 5-worksheet .xlsx workbook into a binary file object."""
    specs = workbook_sheets(db)
    with zipfile.ZipFile(handle, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
        archive.writestr("[Content_Types].xml", content_types_xml(specs))
        archive.writestr("_rels/.rels",
                         XML_DECL + '<Relationships %s>'
                         '<Relationship Id="rId1" Type="%s/officeDocument" Target="xl/workbook.xml"/>'
                         '</Relationships>' % (REL_NS, REL_TYPE))
        archive.writestr("xl/workbook.xml", workbook_xml(specs))
        archive.writestr("xl/_rels/workbook.xml.rels", workbook_rels_xml(specs))
        archive.writestr("xl/styles.xml", STYLES_XML)
        for index, spec in enumerate(specs, 1):
            with archive.open("xl/worksheets/sheet%d.xml" % index, "w", force_zip64=True) as entry:
                write_sheet(spec, entry)


