def build_export_readme(report: dict) -> str:
    lines = []
    add = lines.append
    add("Bamboo-reinforced UHPC bond-slip prediction system")
    add("Batch export report: 27 cases x 5 curves")
    add("================================================================")
    add("")
    add("Generated at: %s" % time.strftime("%Y-%m-%d %H:%M:%S"))
    add("Command: python app.py --export %s" % report["dir"])
    add("")
    add("1. Output files")
    add("1. %s (%s; UTF-8 BOM; 1 header row + %s data rows = %s curve points + %s missing-case marker rows)"
        % (CSV_FILE, human_size(report["csv_bytes"]), format_count(report["csv_data_rows"]),
           format_count(report["total_rows"]), format_count(report["missing_marker_rows"])))
    add("2. %s (%s, 5 worksheets)" % (XLSX_FILE, human_size(report["xlsx_bytes"])))
    add("3. %s (this file)" % README_FILE)
    add("")
    add("2. Data summary (Origin point-by-point data, schema 2.0)")
    add("- Cases: 27 total; available: %d; missing: %d"
        % (report["available_groups"], len(report["missing_groups"])))
    add("- Curves: %d (each available case has 3 specimens + Model 1 + Model 2)" % report["curve_count"])
    add("- Curve points: %s rows (specimens %s rows + models %s rows)"
        % (format_count(report["total_rows"]), format_count(report["specimen_rows"]),
           format_count(report["model_rows"])))
    for treatment in TREATMENTS:
        add("  - %s (%s): %d cases, %s rows"
            % (treatment, treatment_display_name(treatment),
               report["groups_by_treatment"].get(treatment, 0),
               format_count(report["rows_by_treatment"].get(treatment, 0))))
    add("- CSV data rows: %s (%s curve points + %s missing-case markers)"
        % (format_count(report["csv_data_rows"]), format_count(report["total_rows"]),
           format_count(report["missing_marker_rows"])))
    if not report["missing_groups"]:
        add("- Missing cases: none. All 27 cases are complete; UN-L50-D16 was recovered from the Origin "
            "figure embedded in the final paper DOCX (Figure 11a). The X/Y values stored inside that figure "
            "were read out, so nothing here is digitised from a screenshot.")
    else:
        add("- Missing cases: %s (no simulated or digitised values were used)"
            % ", ".join(report["missing_groups"]))
    add("")
    add("3. CSV columns")
    add("- Fixed order: %s (12 columns, numeric columns keep 7 decimals)" % ", ".join(CURVE_HEADERS))
    add("- Normalized slip S/Su and Normalized bond stress tau/tauu are taken directly from Origin's "
        "x_norm/y_norm and are not normalised again.")
    add("- Rebuilt slip_mm = Normalized slip x su; Rebuilt bond stress_MPa = Normalized bond stress x tau_u.")
    add("- Specimens use their own su_repeats_mm/tau_repeats_MPa; Model 1/Model 2 use the group means "
        "su_mm/tau_u_MPa.")
    add("- Curve name: specimens use the paper label (case ID -1/2/3, e.g. UN-L50-D8-1); models use "
        "Model 1 / Model 2.")
    add("- Curve type separates specimen measurements from model curves; Data source separates "
        "Origin measured from Origin model.")
    if not report["missing_groups"]:
        add("- All 27 cases are complete, so the CSV has no missing-case marker rows; see the UN-L50-D16 "
            "provenance above.")
    else:
        add("- A missing case contributes no curve points; one \"Data missing\" marker row is appended at "
            "the end of the CSV so all 27 cases remain visible.")
    add("")
    add("4. Excel worksheets")
    for sheet in report["sheets"]:
        add("- %s: %d rows" % (sheet["name"], sheet["rows"]))
    add("  The summary sheet lists the 27 cases and their data status; the UN/PE/EM curve sheets share "
        "the CSV columns; the notes-and-formulas sheet records the normalisation convention and the "
        "paper formulas.")
    add("")
    add("5. Conventions and limitations")
    add("- Origin's Model 1/Model 2 point arrays are authoritative: this export neither re-fits nor "
        "substitutes formula values.")
    add("- Equation (3) (piecewise) and Equation (4) (rational) of the paper are recorded in the notes "
        "sheet for the GUI's custom parameters only.")
    add("- `--export` does not render the 4 PNG figures (the browser canvas does).")
    add("- All curves are only dimensionally rebuilt for auditing; no negative value is clipped, so "
        "Model 2 may show negative stress at large slip, which is a property of the Origin data itself.")
    return "\n".join(lines) + "\n"


def collect_report(db: dict, directory: str) -> dict:
    specimen_rows, model_rows, groups_by_treatment, rows_by_treatment = collect_export_stats(db)
    report = {
        "dir": directory,
        "missing_groups": missing_curve_groups(db),
        "available_groups": db.get("available_group_count", 0),
        "specimen_rows": specimen_rows,
        "model_rows": model_rows,
        "groups_by_treatment": groups_by_treatment,
        "rows_by_treatment": rows_by_treatment,
        "sheets": [{"name": spec["name"], "rows": spec["row_count"]}
                   for spec in workbook_sheets(db)],
    }
    report["curve_count"] = report["available_groups"] * 5
    report["missing_marker_rows"] = len(report["missing_groups"])
    report["total_rows"] = specimen_rows + model_rows
    report["csv_data_rows"] = report["total_rows"] + report["missing_marker_rows"]
    return report


def write_export_file(path: str, writer) -> int:
    """Write a .tmp file first and rename it, so an interruption never leaves a partial file."""
    tmp_path = path + ".tmp"
    with open(tmp_path, "wb") as handle:
        writer(handle)
    os.replace(tmp_path, path)
    return os.path.getsize(path)


def export_to_directory(db: dict, directory: str) -> dict:
    if not directory or not directory.strip():
        raise ValueError("the export directory must not be empty")
    validate_curve_database(db)
    os.makedirs(directory, exist_ok=True)

    report = collect_report(db, directory)
    report["csv_path"] = os.path.join(directory, CSV_FILE)
    report["xlsx_path"] = os.path.join(directory, XLSX_FILE)
    report["readme_path"] = os.path.join(directory, README_FILE)

    report["csv_bytes"] = write_export_file(
        report["csv_path"], lambda handle: write_curve_csv(handle, db))
    report["xlsx_bytes"] = write_export_file(
        report["xlsx_path"], lambda handle: write_workbook(handle, db))
    write_text_file(report["readme_path"], build_export_readme(report))
    return report


def summary_lines(report: dict) -> list:
    lines = [
        "Status: batch export succeeded (%s)" % report["dir"],
        "CSV : %s (%s, 1 header row + %s data rows = %s curve points + %s missing markers)"
        % (report["csv_path"], human_size(report["csv_bytes"]), format_count(report["csv_data_rows"]),
           format_count(report["total_rows"]), format_count(report["missing_marker_rows"])),
        "XLSX: %s (%s, %d worksheets)"
        % (report["xlsx_path"], human_size(report["xlsx_bytes"]), len(report["sheets"])),
        "Report: %s" % report["readme_path"],
        "Cases: 27/27 available; curves=%d; specimen rows=%s, model rows=%s"
        % (report["curve_count"], format_count(report["specimen_rows"]),
           format_count(report["model_rows"])),
    ]
    for sheet in report["sheets"]:
        lines.append("Worksheet %s: %d rows" % (sheet["name"], sheet["rows"]))
    return lines


def decode_png(encoded: str) -> bytes:
    if encoded.startswith("data:image/png;base64,"):
        encoded = encoded[len("data:image/png;base64,"):]
    data = base64.b64decode(encoded)
    if len(data) < 8 or data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("not a valid PNG file")
    return data


def build_batch_zip(db: dict, images: dict, target_path: str) -> int:
    """CSV + XLSX + 4 PNGs (6 files) written to target_path; returns the file size."""
    validate_curve_database(db)
    decoded = {}
    for name in IMAGE_NAMES:
        encoded = (images or {}).get(name)
        if not encoded:
            raise ValueError("missing plot image: %s" % name)
        decoded[name] = decode_png(encoded)

    with tempfile.TemporaryDirectory() as tmp_dir:
        xlsx_path = os.path.join(tmp_dir, "workbook.xlsx")
        with open(xlsx_path, "wb") as handle:
            write_workbook(handle, db)
        with zipfile.ZipFile(target_path, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
            archive.write(xlsx_path, XLSX_FILE, compress_type=zipfile.ZIP_DEFLATED)
            with archive.open(CSV_FILE, "w", force_zip64=True) as entry:
                write_curve_csv(entry, db)
            for name in IMAGE_NAMES:
                archive.writestr(name, decoded[name])
    return os.path.getsize(target_path)


# ---------------------------------------------------------------------------
# Experimental data import (CSV/TXT/DAT/TSV/XLSX)
# ---------------------------------------------------------------------------

def _decode_text(data: bytes) -> str:
    for encoding in ("utf-8-sig", "gbk"):
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")


def trim_empty_rows(rows: list) -> list:
    out = []
    for row in rows:
        if any(str(value).strip() for value in row):
            out.append(row)
    return out


def parse_delimited_rows(data: bytes, ext: str) -> list:
    text = _decode_text(data).replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    first = ""
    for line in lines:
        if line.strip():
            first = line
            break
    if not first:
        raise ValueError("the file is empty")

    delimiter = None
    if "\t" in first:
        delimiter = "\t"
    elif ";" in first:
        delimiter = ";"
    elif "," in first:
        delimiter = ","

    rows = []
    if delimiter:
        reader = csv.reader(io.StringIO(text), delimiter=delimiter, quotechar='"', skipinitialspace=True)
        for record in reader:
            rows.append(record)
            if len(rows) > MAX_IMPORT_ROWS:
                raise ValueError("more than %d data rows" % MAX_IMPORT_ROWS)
    else:
        for line in lines:
            line = line.strip()
            if not line or line.startswith("#") or line.startswith("//"):
                continue
            rows.append(line.split())
            if len(rows) > MAX_IMPORT_ROWS:
                raise ValueError("more than %d data rows" % MAX_IMPORT_ROWS)
    return trim_empty_rows(rows)


def _local(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _children(element, name: str):
    return [child for child in list(element) if _local(child.tag) == name]


def _first_child(element, name: str):
    for child in list(element):
        if _local(child.tag) == name:
            return child
    return None


def _text_of(element) -> str:
    return "".join(element.itertext()) if element is not None else ""


def column_index(ref: str) -> int:
    index = 0
    for ch in ref:
        if "A" <= ch <= "Z":
            index = index * 26 + (ord(ch) - ord("A") + 1)
        elif "a" <= ch <= "z":
            index = index * 26 + (ord(ch) - ord("a") + 1)
        else:
            break
    return index - 1 if index > 0 else -1


def _shared_strings(archive: zipfile.ZipFile, names: list) -> list:
    if "xl/sharedStrings.xml" not in names:
        return []
    root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
    shared = []
    for si in [child for child in list(root) if _local(child.tag) == "si"]:
        direct = _first_child(si, "t")
        if direct is not None:
            shared.append(_text_of(direct))
            continue
        parts = []
        for run in _children(si, "r"):
            node = _first_child(run, "t")
            if node is not None:
                parts.append(_text_of(node))
        shared.append("".join(parts))
    return shared


def parse_xlsx_rows(data: bytes):
    try:
        archive = zipfile.ZipFile(io.BytesIO(data))
    except zipfile.BadZipFile:
        raise ValueError("not a valid xlsx file")
    with archive:
        names = archive.namelist()
        sheets = sorted(name for name in names
                        if name.startswith("xl/worksheets/") and name.endswith(".xml"))
        if not sheets:
            raise ValueError("the xlsx has no worksheet")
        sheet_path = sheets[0]
        sheet_name = "sheet1.xml"
        for candidate in sheets:
            if candidate.endswith("sheet1.xml"):
                sheet_path = candidate
                sheet_name = "Sheet1"
                break
        shared = _shared_strings(archive, names)
        root = ET.fromstring(archive.read(sheet_path))

    sheet_data = _first_child(root, "sheetData")
    if sheet_data is None:
        raise ValueError("the worksheet has no sheetData")
    rows = []
    max_columns = 0
    for row_element in _children(sheet_data, "row"):
        row = []
        for cell in _children(row_element, "c"):
            index = column_index(cell.get("r", ""))
            if index < 0:
                continue
            while len(row) <= index:
                row.append("")
            value = ""
            value_node = _first_child(cell, "v")
            cell_type = cell.get("t", "")
            if value_node is not None:
                value = _text_of(value_node)
            if cell_type == "s":
                try:
                    position = int(value.strip())
                except ValueError:
                    position = -1
                if 0 <= position < len(shared):
                    value = shared[position]
            elif cell_type == "inlineStr":
                inline = _first_child(cell, "is")
                if inline is not None:
                    direct = _first_child(inline, "t")
                    if direct is not None:
                        value = _text_of(direct)
                    else:
                        value = "".join(_text_of(node) for run in _children(inline, "r")
                                        for node in _children(run, "t"))
            row[index] = value.strip()
        max_columns = max(max_columns, len(row))
        rows.append(row)
    for row in rows:
        while len(row) < max_columns:
            row.append("")
    rows = trim_empty_rows(rows)
    if not rows:
        raise ValueError("the worksheet has no data")
    return rows, sheet_name


# ---------------------------------------------------------------------------
# Local HTTP service
# ---------------------------------------------------------------------------

def parse_multipart(content_type: str, body: bytes) -> dict:
    header = ("Content-Type: %s\r\nMIME-Version: 1.0\r\n\r\n" % content_type).encode("latin-1")
    message = email.message_from_bytes(header + body)
    fields = {}
    for part in message.walk():
        if part.get_content_maintype() == "multipart":
            continue
        disposition = part.get("Content-Disposition", "")
        if "form-data" not in disposition.lower():
            continue
        name = part.get_param("name", header="content-disposition")
        if not name:
            continue
        payload = part.get_payload(decode=True) or b""
        fields[name] = (part.get_filename() or "upload", payload)
    return fields


class BambooHandler(BaseHTTPRequestHandler):
    server_version = "BambooUHPC/1.0"
    protocol_version = "HTTP/1.1"

    # Keep the console clean; errors are reported to the client.
    def log_message(self, fmt, *args):
        pass

    # -- helpers ----------------------------------------------------------
    def send_bytes(self, status: int, content_type: str, payload: bytes, extra=None) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "no-store")
        for key, value in (extra or {}).items():
            self.send_header(key, value)
        self.end_headers()
        self.wfile.write(payload)

    def send_text(self, status: int, text: str) -> None:
        self.send_bytes(status, "text/plain; charset=utf-8", (text + "\n").encode("utf-8"))

    def read_body(self) -> bytes:
        try:
            length = int(self.headers.get("Content-Length") or "0")
        except ValueError:
            length = 0
        if length <= 0:
            return b""
        if length > MAX_UPLOAD:
            raise OverflowError("request body exceeds %d bytes" % MAX_UPLOAD)
        return self.rfile.read(length)

    # -- routing ----------------------------------------------------------
    def do_GET(self):
        path = urllib.parse.urlsplit(self.path).path
        if path in ("/", "/index.html"):
            return self.send_bytes(200, "text/html; charset=utf-8", STATIC_FILES["index.html"])
        if path == "/app.css":
            return self.send_bytes(200, "text/css; charset=utf-8", STATIC_FILES["app.css"])
        if path == "/app.js":
            return self.send_bytes(200, "application/javascript; charset=utf-8", STATIC_FILES["app.js"])
        if path == "/api/data":
            return self.send_bytes(200, "application/json; charset=utf-8", API_BYTES)
        if path in ("/api/import", "/api/export", "/api/quit"):
            return self.send_text(405, "POST only")
        if path == "/favicon.ico":
            return self.send_bytes(204, "image/x-icon", b"")
        return self.send_text(404, "not found")

    def do_POST(self):
        path = urllib.parse.urlsplit(self.path).path
        try:
            if path == "/api/data":
                return self.send_text(405, "GET only")
            if path == "/api/import":
                return self.handle_import()
            if path == "/api/export":
                return self.handle_export()
            if path == "/api/quit":
                return self.handle_quit()
        except OverflowError as exc:
            return self.send_text(413, str(exc))
        except Exception as exc:  # keep the service alive and report in English
            return self.send_text(500, "internal error: %s" % exc)
        return self.send_text(404, "not found")

    # -- endpoints --------------------------------------------------------
    def handle_import(self):
        content_type = self.headers.get("Content-Type", "")
        if "multipart/form-data" not in content_type.lower():
            return self.send_text(400, 'missing form field "file"')
        body = self.read_body()
        fields = parse_multipart(content_type, body)
        if "file" not in fields:
            return self.send_text(400, 'missing form field "file"')
        filename, data = fields["file"]
        ext = os.path.splitext(filename)[1].lower()
        sheet = ""
        try:
            if ext == ".xlsx":
                rows, sheet = parse_xlsx_rows(data)
            elif ext in (".csv", ".txt", ".dat", ".tsv"):
                rows = parse_delimited_rows(data, ext)
            elif ext == ".xls":
                raise ValueError("legacy .xls is not supported; save the file as .xlsx or .csv in Excel first")
            else:
                raise ValueError("unsupported file type %s (supported: csv/txt/dat/tsv/xlsx)" % ext)
            if len(rows) < 2:
                raise ValueError("the file has too few data rows")
        except Exception as exc:
            return self.send_text(400, "import failed: %s" % exc)
        payload = json.dumps({"name": filename, "rows": rows, "sheet": sheet},
                             ensure_ascii=False).encode("utf-8")
        return self.send_bytes(200, "application/json; charset=utf-8", payload)

    def handle_export(self):
        body = self.read_body()
        try:
            request = json.loads(body.decode("utf-8") or "{}")
        except ValueError as exc:
            return self.send_text(400, "invalid export payload: %s" % exc)
        images = request.get("images") or {}
        handle = tempfile.NamedTemporaryFile(delete=False, suffix=".zip")
        zip_path = handle.name
        handle.close()
        try:
            try:
                size = build_batch_zip(CURVE_DB, images, zip_path)
            except Exception as exc:
                return self.send_text(400, "batch export failed: %s" % exc)
            self.send_response(200)
            self.send_header("Content-Type", "application/zip")
            self.send_header("Content-Disposition", 'attachment; filename="Bamboo_UHPC_27cases.zip"')
            self.send_header("Content-Length", str(size))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            with open(zip_path, "rb") as produced:
                while True:
                    chunk = produced.read(1 << 20)
                    if not chunk:
                        break
                    self.wfile.write(chunk)
        finally:
            try:
                os.unlink(zip_path)
            except OSError:
                pass

    def handle_quit(self):
        self.send_bytes(200, "text/plain; charset=utf-8", b"Server stopped")
        server = self.server

        def shutdown():
            time.sleep(0.3)
            server.shutdown()

        threading.Thread(target=shutdown, daemon=True).start()


# ---------------------------------------------------------------------------
# Startup
# ---------------------------------------------------------------------------

def _write_error_log(message: str) -> None:
    try:
        with open(os.path.join(BASE_DIR, "Bamboo_UHPC_error.log"), "w", encoding="utf-8") as handle:
            handle.write(message.strip() + "\n")
    except OSError:
        pass


def _make_console_safe() -> None:
    """Never let an unprintable character kill the start-up on a cp936/cp1252 console."""
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(errors="replace")
        except (AttributeError, ValueError):
            pass


def fatal(message: str) -> int:
    print("Startup failed: %s" % message, file=sys.stderr)
    _write_error_log(message)
    return 1


def default_url_file() -> str:
    return os.path.join(BASE_DIR, "Bamboo_UHPC_url.txt")


def serve_gui(args) -> int:
    global SERVER
    try:
        httpd = ThreadingHTTPServer(("127.0.0.1", args.port), BambooHandler)
    except OSError as exc:
        # An unavailable port is the most common start-up failure on another PC.
        if (exc.errno in (errno.EADDRINUSE, errno.EACCES)
                or getattr(exc, "winerror", None) in PORT_BUSY_WINERRORS):
            return fatal("port %d is not available (already in use or blocked); close the other "
                         "program, or start with --port 0 for a random free port" % args.port)
        return fatal("cannot start the local server on port %d: %s" % (args.port, exc))
    httpd.daemon_threads = True
    SERVER = httpd
    port = httpd.server_address[1]
    url = "http://127.0.0.1:%d/" % port
    print("Local server started: %s" % url, flush=True)

    if args.no_browser:
        print(url, flush=True)
        url_file = args.url_file or default_url_file()
        try:
            directory = os.path.dirname(os.path.abspath(url_file))
            if directory:
                os.makedirs(directory, exist_ok=True)
            with open(url_file, "w", encoding="utf-8") as handle:
                handle.write(url + "\n")
            print("URL written to: %s" % url_file, flush=True)
        except OSError as exc:
            print("Failed to write the URL file: %s" % exc, flush=True)
    else:
        try:
            webbrowser.open(url)
        except Exception as exc:  # noqa: BLE001 - a missing browser must not kill the server
            print("Failed to open a browser automatically; please open %s manually. Error: %s"
                  % (url, exc), flush=True)

    try:
        httpd.serve_forever(poll_interval=0.2)
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


def parse_args(argv=None):
    parser = argparse.ArgumentParser(
        prog="app.py",
        description="Bamboo-UHPC bond-slip prediction system (Python edition, English UI)")
    parser.add_argument("--export", metavar="DIR", default=None,
                        help="Export directory: write CSV/XLSX/README there and exit without the GUI")
    parser.add_argument("--no-browser", action="store_true",
                        help="Do not open a browser; start the local server only")
    parser.add_argument("--port", type=int, default=0,
                        help="Local server port; 0 selects a random free port")
    parser.add_argument("--url-file", metavar="FILE", default=None,
                        help="Write the access URL to this file (default: Bamboo_UHPC_url.txt beside app.py)")
    return parser.parse_args(argv)


def main(argv=None) -> int:
    _make_console_safe()
    args = parse_args(argv)
    if not 0 <= args.port <= 65535:
        return fatal("--port must be between 0 and 65535, got %d" % args.port)
    if args.export is not None and not str(args.export).strip():
        return fatal("--export requires a non-empty directory")

    try:
        load_databases()
    except Exception as exc:  # noqa: BLE001 - startup must report any data problem in English
        return fatal(str(exc))

    if args.export is not None:
        try:
            report = export_to_directory(CURVE_DB, args.export)
        except Exception as exc:  # noqa: BLE001
            print("Batch export failed: %s" % exc, file=sys.stderr)
            return 1
        for line in summary_lines(report):
            print(line, flush=True)
        return 0

    return serve_gui(args)


if __name__ == "__main__":
    if sys.version_info < MIN_PYTHON:
        sys.stderr.write("Python %d.%d or later is required; this interpreter is %d.%d.\n"
                         % (MIN_PYTHON[0], MIN_PYTHON[1],
                            sys.version_info[0], sys.version_info[1]))
        sys.exit(2)
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.exit(0)
